  font-family: 'All-ProSans';
  font-weight: normal;
  font-style: normal;
  src: url('https://cdn.riddle.com/website/fonts/NFL/All-ProSans-Regular.woff2') format('woff2');
}

@font-face {
   font-family: "AllProDisplayC-Bold";
   src: url("https://p.nfltags.com/nfl/fonts/allprodisplayc/bold.woff2") format("woff2"),url("https://p.nfltags.com/nfl/fonts/allprodisplayc/bold.woff") format("woff");
   font-weight: "normal";
   font-style: normal;
   font-display: block;
}

@font-face {
   font-family: "All-ProSans-Bold";
   src: url("https://p.nfltags.com/nfl/fonts/allpro-sans/bold.woff2") format("woff2"),url("https://p.nfltags.com/nfl/fonts/allpro-sans/bold.woff") format("woff");
   font-weight: "normal";
   font-style: normal;
   font-display: block;
}

.rf-modal-content-wrapper {
  height: 512px !important;
  justify-content: center;  
  border-radius: 12px !important;
  box-shadow: 0px -8px 19px 0px rgba(0, 0, 0, 0.35) !important;
}

.rf-header {
  font-family: 'AllProDisplayC-Bold', 'fontDisplay', 'fontDisplay Fallback';
  font-style: italic;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0px;
  line-height: 30px;
  text-align: center;
  font-size: 28px;
  display: inline-block;
  max-width: 875px;
  margin-bottom: 16px;
}

.top-img {
  display: block;
  margin: 0 auto;
  width: 210px;
}

.paywall-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 48px 64px;
  background-color: #f0f0f0;
  border: 2px solid #e0e0e0;
  border-radius: 4px;
  max-width: 720px;
  margin: 0 auto;
  min-height: 100%;
  justify-content: space-between;
  box-sizing: border-box;
  font-family: Georgia, 'Times New Roman', serif;
}

.rf-paywall-header {
  color: black; 
  font-size: 11px;
  text-transform: uppercase;
  border-bottom: 1px solid #D2DAE1;
  text-align: center;
  padding-bottom: 4px;
  font-weight: 600;
  font-family: "All-ProSans-Bold";
}

.paywall-logo-bar {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 24px;
}

.logo-nfl {
  height: 32px;
  width: auto;
}

.logo-divider {
  font-size: 24px;
  color: #999;
  font-weight: 300;
}

.logo-athletic {
  font-size: 22px;
  font-weight: 700;
  color: #111;
  font-family: Georgia, serif;
  letter-spacing: -0.3px;
}

.paywall-title {
  font-family: 'Arial Black', 'Helvetica Neue', sans-serif;
  font-weight: 900;
  font-style: italic;
  font-size: 34px;
  line-height: 1.1;
  text-transform: uppercase;
  color: #111111;
  margin: 0 0 20px 0;
  max-width: 560px;
}

.paywall-subtitle {
  font-size: 20px;
  color: #626C80;
  line-height: 28px;
  white-space: normal;
  font-family: fontSans, 'All-ProSans', 'All-ProSans-Regular' !important;
}

.paywall-body {
  font-size: 16px;
  display: block;
  margin: 0 auto;
  max-width: 768px;
  margin-top: -26px;
  color: #666;
  line-height: 22px;
  font-family: fontSans, 'All-ProSans', 'All-ProSans-Regular' !important;

}

.paywall-buttons {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin-bottom: 20px;
}

.paywall-signin {
  font-size: 13px;
  color: #333;
  font-weight: 600;
  padding-bottom: 18px;
  font-family: "All-ProSans-Bold";
  border-bottom: 1px solid #ddd;  
  line-height: 12px;
}

.signin-link {
  color: #000 !important;
  text-decoration: none;
  font-weight: 700;
}

.signin-link:hover {
  text-decoration: underline;
}

.paywall-terms {
  font-family: "All-ProSans-Bold";
  position: relative;
  font-size: 11px;
  color: #999;
  margin: 0;
  width: 100%;
  height: 24px;
  margin-top: auto;
}

.promo-tile-wrapper-body div {
  white-space: normal;
}

.rf-buttons-inner div {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.rf-buttons-inner div button {
  width: 200px !important;
  height: 48px;
  border-radius: 4px !important;
  font-family: 'AllProDisplayC-Bold', 'fontDisplay', 'fontDisplay Fallback';
  font-size: 16px !important;
}

.rfmodal-button-yes.primary-btn-p {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 18px;
  margin-right: 0 !important;
  background: linear-gradient(111.34deg, #004FFF 0%, #003FCC 100%) !important;
}

.promo-tile-wrapper-btn-no {
  border: 1px solid #004FFF;
}

.secondary-btn-p {
  margin-left: 0 !important;
  border: 1px solid #004FFF;
}

.promo-tile-wrapper-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.promo-tile-wrapper-header {
  white-space: normal;
}

.rfmodal-header-mobileweb .rf-header {
  font-size: 24px;
  line-height: 28px;
  margin-bottom: 8px;
}

.rfmodal-header {
  margin-bottom: 12px !important;
}

.rfmodal-message-mobileweb .paywall-subtitle {
  font-size: 16px !important;
  line-height: 24px;
  text-align: center;
  margin-bottom: 8px !important;
}

.rfmodal-message-mobileweb .paywall-body {
  font-size: 14px !important;
  line-height: 18px;
  text-align: center;
  margin: -24px 16px 12px 16px;
}

.rfmodal-message-mobileweb .paywall-terms {
  text-align: center;
}

.rfmodal-header-mobileweb {
  margin-top: 8px;
}

.rfmodal-header-mobileweb .rf-paywall-header {
  width: 100%;
  display: inline-block;
  margin-bottom: 20px;
  padding-bottom: 16px !important;
}

.rf-small-terms {
  font-family: fontSans, 'All-ProSans', 'All-ProSans-Regular' !important;
  color: #626C80;
  padding-top: 12px;
}

.rfmodal-footer-mobileweb div button {
  width: 199px !important;
  height: 56px !important;
  padding: 16px 0 !important;
  font-family: 'AllProDisplayC-Bold', 'fontDisplay', 'fontDisplay Fallback' !important;
}

.promo-tile-wrapper-body {
  padding-bottom: 24px !important;
}

.rfmodal-inner-wrapper {
  padding: 0 !important;
}

.rfmodal-colm-spacer {
  display: none;
}

.mobileWebModalWrapper {
  width: 100% !important;
  border-radius: 12px !important;
  box-shadow: 0px -8px 19px 0px rgba(0, 0, 0, 0.35) !important;
  padding: 0px;
}

.rfmodal-footer-mobileweb div {
  display: flex;
  align-items: center;
  flex-direction: column;
}

/* push to bottom */
.rfmodal-content.center-modal {
  top: auto;                    /* remove top: 50% centering */
  bottom: 0;                    /* anchor to bottom of viewport */
  left: 50%;                    /* keep horizontal centering */
  transform: translateX(-50%);  /* horizontal only, drop the vertical -50% */
  border-radius: 12px 12px 0 0; /* flat bottom, rounded top */
  width: 100% !important;
}

.modal-privacy-tos {
  position: relative!important;
}

/* Mobile */

.modal-mobileweb-display {
  display: flex;
  align-items: flex-end;
}

.mobileWebModalWrapper {
  top: auto;
  bottom: 0;
  left: 0;
  transform: none;             
  width: 100%;
  border-radius: 12px 12px 0 0;
}
/* MEDIA QUERIES*/
@media (max-width: 678px) {
  .paywall-subtitle {
    font-size: 20px;
  }
}

.rfmodal-header-mobileweb h3 .rf-header {
  display: block;  
  text-align: center;
  margin: 0 auto;
}
@media (max-width: 613px) {

  /* Footer keeps its normal place in the DOM */
  .rfmodal-footer {
    margin-top: 0;
    margin-bottom: 0;
    flex-shrink: unset;
  }

  .rfmodal-footer-mobileweb {
    margin-bottom: 12px; /* reserve room for sign-in + terms below buttons */
  }

  /* Pin sign-in/terms below the button stack */
  .paywall-terms {
    width: 100%;
    height: auto;
    margin: auto;
    padding: 0 16px;
    box-sizing: border-box;
    text-align: center;
  }

  .paywall-signin {
    margin: 0 0 8px;
    padding-bottom: 8px;
    line-height: 1.3;
  }

  .rfmodal-message-mobileweb .paywall-subtitle {
    margin-bottom: 8px !important;
  }

  .rfmodal-message-mobileweb .paywall-body {
    margin: 0 16px !important;
  }
  .rf-header {
  font-size: 30px;
  }
.paywall-subtitle {
  font-size: 20px;
}
.paywall-body {
  font-size: 13px;
  }
}

.rfmodal-button-yes {
  text-transform: uppercase;
}

.rfmodal-body {
  margin-bottom: 4px !important;
}

